matlab_function:
function y = MatGuard(x)
ep = jsondecode(getenv('GMAT_QT_MATLAB_CALLBACK'));
c = tcpclient('127.0.0.1', ep.port, 'Timeout', 10);
configureTerminator(c, 'LF');
request = ['{"token":"', ep.token, '","op":"evaluate","x":[2],"id":1}', newline];
write(c, uint8(request));
reply = jsondecode(char(readline(c)));
assert(~reply.ok && contains(reply.error, 'GMAT-called MATLAB function cannot'), 'Expected GMAT reentry restriction');
y = 3*x + 2;
end
